from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    walls = []
    for r, row in enumerate(grid):
        if row and len(set(row)) == 1 and row[0] != bg:
            walls.append(('h', r, row[0]))
    for c in range(w):
        vals = [grid[r][c] for r in range(h)]
        if len(set(vals)) == 1 and vals[0] != bg:
            walls.append(('v', c, vals[0]))
    if not walls:
        return [row[:] for row in grid]
    # The long full-width/full-height separator is the movement boundary.
    axis, wall, _ = max(walls, key=lambda x: h*w)
    points = [(r,c) for r in range(h) for c in range(w) if grid[r][c] != bg and not (r == wall if axis == 'h' else c == wall)]
    if not points:
        return [row[:] for row in grid]
    out = [row[:] for row in grid]
    for r,c in points:
        out[r][c] = bg
    if axis == 'h':
        if max(r for r,c in points) < wall:
            dr = wall - 1 - max(r for r,c in points)
            stripe = min(r for r,c in points) + dr - 1
        else:
            dr = wall + 1 - min(r for r,c in points)
            stripe = max(r for r,c in points) + dr + 1
        moved = [(r+dr,c) for r,c in points]
        for r,c in moved: out[r][c] = grid[next((rr for rr,cc in points if cc==c and rr==r-dr), r-dr)][c] if False else next(grid[rr][cc] for rr,cc in points if (rr+dr,cc)==(r,c))
        if 0 <= stripe < h:
            out[stripe] = [8]*w
    else:
        if max(c for r,c in points) < wall:
            dc = wall - 1 - max(c for r,c in points)
            stripe = min(c for r,c in points) + dc - 1
        else:
            dc = wall + 1 - min(c for r,c in points)
            stripe = max(c for r,c in points) + dc + 1
        moved = [(r,c+dc) for r,c in points]
        for r,c in moved:
            out[r][c] = next(grid[rr][cc] for rr,cc in points if (rr,cc+dc)==(r,c))
        if 0 <= stripe < w:
            for r in range(h): out[r][stripe] = 8
    return out

